// Save to database via bulkCreate with upsert
const dbRecords = instruments.map(item => ({
  symbol: item.symbol,
  name: item.name,
  type: item.type,
  market: item.market || null,
  category: item.category || null,
  listing_date: item.listing_date || null,
  status: item.status || 'active',
}));

const dbResult = await Instrument.bulkCreate(dbRecords, {
  updateOnDuplicate: ['name', 'type', 'market', 'category', 'listing_date', 'status', 'updated_at'],
  validate: true,
});

console.log(`✅ 成功持久化 ${dbResult.length} 个标的到数据库`);

// Backup to filesystem
let filePath = null;
try {
  const fs = require('fs');
  const path = require('path');
  const dataDir = path.join(__dirname, '../../data');

  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  filePath = path.join(dataDir, 'instruments.json');
  fs.writeFileSync(filePath, JSON.stringify({
    data: instruments,
    timestamp: Date.now(),
    count: instruments.length
  }, null, 2));
} catch (fileErr) {
  console.warn('⚠️ 文件备份写入失败 (数据库已保存):', fileErr.message);
}

res.json({
  success: true,
  data: {
    count: dbResult.length,
    filePath
  },
  message: '标的列表持久化成功'
});

